-- Generated by scripts/import-igdb-games.mjs
-- Top 100 games per curated platform, sorted by IGDB total_rating_count.
-- Paste into the Supabase SQL editor after running schema.sql.

on conflict (id) do update set
  name      = excluded.name,
  year      = excluded.year,
  genre     = excluded.genre,
  platforms = excluded.platforms;

-- Extend: pages 2-4 (ranks 200-499) for platforms newer than SNES.
-- Appended 2026-05-25 by scripts/import-igdb-games.mjs --extend
on conflict (id) do update set
  name      = excluded.name,
  year      = excluded.year,
  genre     = excluded.genre,
  platforms = excluded.platforms;

-- Extend: pages 5-6 (ranks 500-699) for platforms newer than SNES.
-- Appended 2026-06-03 by scripts/import-igdb-games.mjs --extend
on conflict (id) do update set
  name      = excluded.name,
  year      = excluded.year,
  genre     = excluded.genre,
  platforms = excluded.platforms;

-- ── CUSTOM ADDITIONS ────────────────────────────────────────────────────────
-- Manually-added obscure games. Edit name / year / genre / platforms before
-- running. IDs live in the 9_000_000+ range so they never collide with IGDB
-- ids pulled by scripts/import-igdb-games.mjs.
on conflict (id) do update set
  name      = excluded.name,
  year      = excluded.year,
  genre     = excluded.genre,
  platforms = excluded.platforms;

-- Year: top 2026 releases (by hypes) for current platforms (PC, PS5, Xbox Series, Switch).
-- Appended 2026-06-21 by scripts/import-igdb-games.mjs --year=2026
on conflict (id) do update set
  name      = excluded.name,
  year      = excluded.year,
  genre     = excluded.genre,
  platforms = excluded.platforms;
